 JSONObject http(JSONObject a)throws Exception{URL url=new URL(a.getString("url"));if(!url.getProtocol().equals("https")&&!url.getProtocol().equals("http"))throw new Exception("HTTP or HTTPS is required.");String method=a.optString("method","GET");if(!Arrays.asList("GET","POST","PUT","DELETE","PROPFIND","MKCOL").contains(method))throw new Exception("This HTTP method is not allowed.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(45000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);JSONObject headers=a.optJSONObject("headers");if(headers!=null)for(Iterator<String> it=headers.keys();it.hasNext();){String name=it.next();c.setRequestProperty(name,headers.getString(name));}if(a.has("body")||a.has("bodyBase64")){c.setDoOutput(true);byte[] body=a.has("bodyBase64")?android.util.Base64.decode(a.getString("bodyBase64"),2):a.getString("body").getBytes(java.nio.charset.StandardCharsets.UTF_8);if(body.length>128*1024*1024)throw new IOException("Upload exceeds 128 MB.");try(OutputStream out=c.getOutputStream()){out.write(body);}}int code=c.getResponseCode();if(code>=300&&code<400&&!a.optBoolean("noRedirect")){String next=c.getHeaderField("Location");c.disconnect();if(a.optInt("redirects")>=5)throw new Exception("Too many redirects.");URL dest=new URL(url,next);if(!url.getHost().equalsIgnoreCase(dest.getHost())&&headers!=null){headers.remove("Authorization");headers.remove("Cookie");}if("https".equals(url.getProtocol())&&!"https".equals(dest.getProtocol()))throw new Exception("Refusing an insecure redirect.");a.put("url",dest.toString()).put("redirects",a.optInt("redirects")+1);return http(a);}InputStream in=code>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(in!=null){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>128*1024*1024)throw new Exception("Download exceeds 128 MB.");bytes.write(buffer,0,n);}in.close();}JSONObject responseHeaders=new JSONObject();for(Map.Entry<String,List<String>> entry:c.getHeaderFields().entrySet())if(entry.getKey()!=null)responseHeaders.put(entry.getKey(),String.join(",",entry.getValue()));c.disconnect();return new JSONObject().put("status",code).put("body",android.util.Base64.encodeToString(bytes.toByteArray(),2)).put("headers",responseHeaders);}
 private JSONArray listFiles(String value)throws Exception{if(value.isEmpty())return new JSONArray();Uri parent=Uri.parse(value);if("file".equals(parent.getScheme())){File[] children=StorageAccess.file(this,parent).listFiles();if(children==null)throw new IOException("This folder cannot be read.");JSONArray result=new JSONArray();for(File child:children)result.put(new JSONObject().put("uri",Uri.fromFile(child).toString()).put("name",child.getName()).put("directory",child.isDirectory()).put("size",child.length()));return result;}String docId=DocumentsContract.isTreeUri(parent)?DocumentsContract.getDocumentId(parent):null;if(docId==null)docId=DocumentsContract.getTreeDocumentId(parent);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(parent,docId);JSONArray list=new JSONArray();try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE},null,null,null)){while(c!=null&&c.moveToNext())list.put(new JSONObject().put("uri",DocumentsContract.buildDocumentUriUsingTree(parent,c.getString(0)).toString()).put("name",c.getString(1)).put("directory",DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2))).put("size",c.getLong(3)));}return list;}
 private JSONObject stage(Uri uri)throws Exception{String name="file".equals(uri.getScheme())?StorageAccess.file(this,uri).getName():"book";if(!"file".equals(uri.getScheme()))try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}String staged=UUID.randomUUID().toString();File f=new File(getCacheDir(),staged);try(InputStream in=StorageAccess.input(this,uri);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[32768];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>256*1024*1024)throw new Exception("Book exceeds 256 MB.");out.write(b,0,n);}}return new JSONObject().put("name",name).put("sourceUri",uri.toString()).put("url",ORIGIN+"/imports/"+staged);}
 private void persistPermission(Uri uri,int granted){
  boolean read=(granted&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0,write=(granted&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0;
  if(read&&write)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
  else if(read)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);
  else if(write)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
 }
 @Override protected void onActivityResult(int request,int code,Intent data){super.onActivityResult(request,code,data);if(google.activityResult(request,code,data))return;if(request==104){String id=backgroundTreeId;backgroundTreeId=null;if(code!=RESULT_OK||data==null){result(id,false,"Folder selection cancelled.");return;}Uri uri=data.getData();persistPermission(uri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);String doc=DocumentsContract.buildDocumentUriUsingTree(uri,DocumentsContract.getTreeDocumentId(uri)).toString();result(id,true,doc);return;}if(request==103){String id=pickBooksId;pickBooksId=null;if(code!=RESULT_OK||data==null){result(id,true,new JSONArray());return;}ArrayList<Uri> selected=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)selected.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)selected.add(data.getData());int grants=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);for(Uri uri:selected)try{persistPermission(uri,grants);}catch(Exception ignored){}pool.execute(()->{try{JSONArray files=new JSONArray();for(Uri uri:selected)files.put(stage(uri));result(id,true,files);}catch(Exception error){result(id,false,error.getMessage());}});return;}if(request==100){if(fileCallback!=null){ArrayList<Uri> uris=new ArrayList<>();if(code==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());}fileCallback.onReceiveValue(uris.toArray(new Uri[0]));fileCallback=null;}}else if(request==101){String id=saveId;byte[] bytes=saveBytes;saveId=null;saveBytes=null;if(code!=RESULT_OK||data==null){result(id,false,"Save cancelled.");return;}Uri uri=data.getData();pool.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);result(id,true,true);}catch(Exception e){result(id,false,e.getMessage());}});}else if(request==102){if(code!=RESULT_OK||data==null){result(treeId,false,"Folder selection cancelled.");return;}Uri uri=data.getData();persistPermission(uri,data.getFlags());String document=DocumentsContract.buildDocumentUriUsingTree(uri,DocumentsContract.getTreeDocumentId(uri)).toString();prefs().edit().putString("tree",document).apply();result(treeId,true,document);}}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);if(pageReady)handleIntent(i);else pendingIntent=i;}
 private void handleIntent(Intent i){if(i==null)return;if(i.hasExtra("book"))event("openBook",i.getStringExtra("book"));Uri uri=i.getData();if(Intent.ACTION_SEND.equals(i.getAction()))uri=i.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null&&"content".equals(uri.getScheme())){Uri target=uri;pool.execute(()->{try{event("import",stage(target));}catch(Exception e){event("error",e.getMessage());}});}pendingIntent=null;}
 @Override public boolean dispatchKeyEvent(KeyEvent e){
  if(e.getAction()==KeyEvent.ACTION_DOWN&&captureHardwareKey&&e.getKeyCode()!=KeyEvent.KEYCODE_BACK){captureHardwareKey=false;event("keycode",e.getKeyCode());return true;}
  if(prefs().getBoolean("reading",false)&&hardwareKeys.has(String.valueOf(e.getKeyCode()))){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)event("key","custom:"+e.getKeyCode());return true;}

  if(e.getAction()==KeyEvent.ACTION_DOWN&&SpeechService.active){String speechAction=null;switch(e.getKeyCode()){case KeyEvent.KEYCODE_HEADSETHOOK:case KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE:speechAction="toggle";break;case KeyEvent.KEYCODE_MEDIA_NEXT:speechAction="next";break;case KeyEvent.KEYCODE_MEDIA_PREVIOUS:speechAction="previous";break;case KeyEvent.KEYCODE_MEDIA_STOP:speechAction="stop";break;}if(speechAction!=null){startService(new Intent(this,SpeechService.class).setAction(speechAction));return true;}}

  if(e.getAction()==KeyEvent.ACTION_DOWN&&prefs().getBoolean("reading",false)){
   String name=null;switch(e.getKeyCode()){
    case KeyEvent.KEYCODE_VOLUME_UP:if(prefs().getBoolean("volumeKeys",true))name="volumeUp";break;
    case KeyEvent.KEYCODE_VOLUME_DOWN:if(prefs().getBoolean("volumeKeys",true))name="volumeDown";break;
    case KeyEvent.KEYCODE_MENU:name="menu";break;case KeyEvent.KEYCODE_SEARCH:name="search";break;case KeyEvent.KEYCODE_CAMERA:name="camera";break;
    case KeyEvent.KEYCODE_DPAD_UP:name="dpadUp";break;case KeyEvent.KEYCODE_DPAD_DOWN:name="dpadDown";break;case KeyEvent.KEYCODE_DPAD_LEFT:name="dpadLeft";break;case KeyEvent.KEYCODE_DPAD_RIGHT:name="dpadRight";break;case KeyEvent.KEYCODE_DPAD_CENTER:name="dpadCenter";break;
    case KeyEvent.KEYCODE_HEADSETHOOK:name="headset";break;case KeyEvent.KEYCODE_MEDIA_NEXT:name="mediaNext";break;case KeyEvent.KEYCODE_MEDIA_PREVIOUS:name="mediaPrevious";break;case KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE:name="mediaPause";break;
   }if(name!=null){event("key",name);return true;}
  }return super.dispatchKeyEvent(e);
 }
