 @Override protected void onResume(){super.onResume();if(sensors!=null)sensors.registerListener(this,sensors.getDefaultSensor(Sensor.TYPE_ACCELEROMETER),SensorManager.SENSOR_DELAY_UI);if(web!=null)event("resume",true);}
 @Override protected void onPause(){super.onPause();if(sensors!=null)sensors.unregisterListener(this);if(web!=null)event("pause",true);}
 @Override protected void onDestroy(){if(speechVoices!=null)speechVoices.destroy();super.onDestroy();if(google!=null)google.destroy();if(speechReceiver!=null)unregisterReceiver(speechReceiver);if(voiceDownloadReceiver!=null)unregisterReceiver(voiceDownloadReceiver);pool.shutdown();if(web!=null)web.destroy();}
 @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
 @Override public void onSensorChanged(SensorEvent e){if(System.currentTimeMillis()-lastSensor<1800)return;double force=Math.sqrt(e.values[0]*e.values[0]+e.values[1]*e.values[1]+e.values[2]*e.values[2]);if(shake&&force>shakeThreshold){lastSensor=System.currentTimeMillis();event("shake",true);}else if(tilt&&Math.abs(e.values[0])>7){lastSensor=System.currentTimeMillis();event("tilt",e.values[0]>0?"previous":"next");}}
